const TokenKey = 'Admin-Token'
const tmpTokenKey = 'Tmp-Token'

export function getToken() {
  return sessionStorage.getItem(TokenKey)
}

export function setToken(token) {
  setLoggingOut(false)
  return sessionStorage.setItem(TokenKey, token)
}

export function removeToken() {
  return sessionStorage.removeItem(TokenKey)
}

// -------------------------------------
export function getTmpToken() {
  return sessionStorage.getItem(tmpTokenKey)
}

export function setTmpToken(token) {
  return sessionStorage.setItem(tmpTokenKey, token)
}

export function removeTmpToken() {
  return sessionStorage.removeItem(tmpTokenKey)
}
