// 处理已登录状态下的路由跳转
const handleAuthenticatedRoutes = async (to, next) => {
  // 设置页面标题
  if (to.meta.title) {
    // 使用Vuex替代Pinia
    store.commit('settings/SET_TITLE', to.meta.title)
  }

  // 已登录用户访问登录页时重定向到首页
  if (to.path === '/login') {
    next({ path: '/index', replace: true })
    return
  }

  // 检查白名单
  if (whiteList.includes(to.path)) {
    next()
    return
  }

  // 检查用户角色和权限
  if (store.getters.roles.length === 0) {
    try {
      // 获取用户信息
      const res = await store.dispatch('GetInfo')

      // 并行获取基础数据
      await Promise.all([
        store.dispatch('app/getPlatformConfig'),
        store.dispatch('common/saveBizStateOption'),
        store.dispatch('common/saveAreaInfo'),
        store.dispatch('common/getRegions')
      ])

      // 生成并添加权限路由
      const accessRoutes = await store.dispatch('GenerateRoutes')
      accessRoutes.forEach(route => {
        if (route.path) {
          router.addRoute(route)
        }
      })

      // 确保新路由已添加完成后再跳转
      next({ ...to, replace: true })
    } catch (error) {
      console.error('路由权限加载失败:', error)
      // 确保Logout方法返回Promise，避免调用undefined的catch方法
      const logoutResult = store.dispatch('FedLogOut');
      if (logoutResult && typeof logoutResult.catch === 'function') {
        await logoutResult.catch(err => console.error('登出失败:', err));
      } else {
        await logoutResult;
      }
      next(`/login?redirect=${encodeURIComponent(to.fullPath)}`)
    }
  } else {
    next()
  }
}

tool_input.new_string:
// 初始化用户信息与动态权限路由（GetInfo + 基础数据 + GenerateRoutes + addRoute）
// 仅负责初始化并通过 resolve/reject 返回成功/失败，next() 调用交由调用方决定，
// 避免破坏常规分支 next({ ...to, replace: true }) 携带原目标重新进入守卫的语义。
const initUserAndRoutes = async () => {
  // 获取用户信息
  await store.dispatch('GetInfo')

  // 并行获取基础数据
  await Promise.all([
    store.dispatch('app/getPlatformConfig'),
    store.dispatch('common/saveBizStateOption'),
    store.dispatch('common/saveAreaInfo'),
    store.dispatch('common/getRegions')
  ])

  // 生成并添加权限路由
  const accessRoutes = await store.dispatch('GenerateRoutes')
  accessRoutes.forEach(route => {
    if (route.path) {
      router.addRoute(route)
    }
  })
}

// 登出并兜底跳转登录页（token 清除完成后 next，且不带 redirect，避免死循环）
const logoutAndRedirect = async (next) => {
  const logoutResult = store.dispatch('FedLogOut')
  if (logoutResult && typeof logoutResult.catch === 'function') {
    await logoutResult.catch(err => console.error('登出失败:', err))
  } else {
    await logoutResult
  }
  next('/login')
}

// 处理已登录状态下的路由跳转
const handleAuthenticatedRoutes = async (to, next) => {
  // 设置页面标题
  if (to.meta.title) {
    // 使用Vuex替代Pinia
    store.commit('settings/SET_TITLE', to.meta.title)
  }

  // 已登录用户访问登录页时重定向到首页
  // 需先完成用户信息与动态权限路由初始化，否则跳 /index 后会因无权被回退到 /login
  if (to.path === '/login') {
    if (store.getters.roles.length === 0) {
      try {
        await initUserAndRoutes()
        next({ path: '/index', replace: true })
      } catch (error) {
        console.error('路由权限加载失败:', error)
        await logoutAndRedirect(next)
      }
    } else {
      next({ path: '/index', replace: true })
    }
    return
  }

  // 检查白名单
  if (whiteList.includes(to.path)) {
    next()
    return
  }

  // 检查用户角色和权限
  if (store.getters.roles.length === 0) {
    try {
      await initUserAndRoutes()
      // 确保新路由已添加完成后再跳转
      next({ ...to, replace: true })
    } catch (error) {
      console.error('路由权限加载失败:', error)
      await logoutAndRedirect(next)
    }
  } else {
    next()
  }
}

